function contractDaysUntil(date) {
  if (!date) return null;
  const target = new Date(`${date}T23:59:59`);
  const now = new Date();
  return Math.ceil((target.getTime() - now.getTime()) / 86400000);
}

function contractRisk(document) {
  if (document.status === "Archived") return { label: "Archived", tone: "gray", rank: 6 };
  if (!document.expiryDate) return { label: "No Expiry", tone: "blue", rank: 5 };
  const days = contractDaysUntil(document.expiryDate);
  if (days < 0) return { label: "Expired", tone: "red", rank: 0 };
  if (document.escalatedAt) return { label: "Escalated", tone: "red", rank: 1 };
  if (days <= 30) return { label: "Critical", tone: "red", rank: 2 };
  if (days <= 90) return { label: "Expiring", tone: "amber", rank: 3 };
  return { label: "Active", tone: "green", rank: 4 };
}

function contractEmployeeName(id, employees) {
  return employees.find(employee => employee.id === id)?.preferredName || "Unassigned";
}

function contractEntityName(id) {
  return HR_LEGAL_ENTITIES.find(entity => entity.id === id)?.name || "Unassigned entity";
}

