function marketEntityName(id, entities){ return entities.find(x=>x.id===id)?.name || "Unknown source"; }
function marketPriorityTone(priority){ return priority==="Critical"?"red":priority==="High"?"amber":priority==="Medium"?"blue":"gray"; }
function marketStatusTone(status){ const s=String(status||"").toLowerCase(); return s.includes("healthy")||s.includes("launched")||s.includes("closed")||s.includes("published")?"green":s.includes("critical")||s.includes("failed")||s.includes("limited")?"red":s.includes("partial")||s.includes("review")||s.includes("approval")?"amber":s.includes("draft")||s.includes("assigned")?"blue":"gray"; }

function MarketRadarModal({title,onClose,footer,children,wide=false}){
  return <div className="modal-backdrop"><div className={`modal market-modal ${wide?"wide":""}`}><div className="modal-head"><h3>{title}</h3><button onClick={onClose}>×</button></div><div className="modal-body">{children}</div>{footer&&<div className="modal-foot">{footer}</div>}</div></div>;
}

