function crmUsd(value){ return new Intl.NumberFormat("en-US",{style:"currency",currency:"USD",maximumFractionDigits:0}).format(Number(value||0)); }
function crmIdr(value){ return new Intl.NumberFormat("id-ID",{style:"currency",currency:"IDR",maximumFractionDigits:0}).format(Number(value||0)); }
function crmIdrCompact(value){ const n=Number(value||0); if(Math.abs(n)>=1e9)return `IDR ${(n/1e9).toFixed(n>=1e10?1:2).replace(/\.00$/,"")} B`; if(Math.abs(n)>=1e6)return `IDR ${(n/1e6).toFixed(n>=1e8?0:1).replace(/\.0$/,"")} M`; return crmIdr(n); }
function crmPct(a,b){ return b?Math.round(a/b*1000)/10:0; }
function crmMinutes(a,b){ if(!a||!b) return null; return Math.max(0,Math.round((new Date(b)-new Date(a))/60000)); }
function crmMedian(values){ const a=values.filter(v=>Number.isFinite(v)).sort((x,y)=>x-y); if(!a.length)return 0; const m=Math.floor(a.length/2); return a.length%2?a[m]:Math.round((a[m-1]+a[m])/2); }
function crmResponseMinutes(lead){ return crmMinutes(lead.receivedAt,lead.firstHumanResponseAt); }
function crmResponseState(lead){ const m=crmResponseMinutes(lead); if(m===null){ const elapsed=crmMinutes(lead.receivedAt,new Date().toISOString()); if(elapsed>lead.slaMinutes*2)return {label:"Escalated",tone:"red",minutes:elapsed}; if(elapsed>lead.slaMinutes)return {label:"Overdue",tone:"red",minutes:elapsed}; return {label:"Awaiting",tone:"amber",minutes:elapsed}; } return m<=lead.slaMinutes?{label:"Within SLA",tone:"green",minutes:m}:{label:"Late",tone:"red",minutes:m}; }


