function crmFrontInitials(name){return String(name||"?").split(/\s+/).slice(0,2).map(x=>x[0]).join("").toUpperCase()}
function crmFrontDate(ts){if(!ts)return "—";try{return new Intl.DateTimeFormat("en-GB",{day:"2-digit",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit"}).format(new Date(ts))}catch{return ts}}
function crmFrontDownload(filename,html){const blob=new Blob([html],{type:"text/html;charset=utf-8"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1200)}
function crmActiveTemplate(templates,family){return templates.find(t=>t.family===family&&t.status==="Active")||templates.find(t=>t.family===family)}
function crmProposalHtml(p,contact,templates){const t=family=>crmActiveTemplate(templates,family);return `<!doctype html><html><head><meta charset="utf-8"><title>${p.title}</title><style>body{margin:0;font-family:Arial;color:#172033;background:#f2f3f5}.wrap{max-width:980px;margin:36px auto;background:white}.hero{padding:72px 64px;background:linear-gradient(135deg,#0d2436,#294d5d);color:white}.brand{letter-spacing:8px;font-family:Georgia;font-size:24px}.gold{color:#d5be78}.body{padding:46px 64px}.kicker{letter-spacing:3px;color:#9d8750;font-weight:bold}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:26px 0}.grid div{padding:16px;background:#f7f8fa;border:1px solid #e7e9ed}.day{padding:18px 0;border-top:1px solid #e6e8eb}.price{font-size:32px;font-family:Georgia}.fine{font-size:12px;color:#6d7684}.cta{display:inline-block;background:#bea55f;color:white;padding:14px 24px;text-decoration:none;border-radius:4px}</style></head><body><div class="wrap"><section class="hero"><div class="brand">SAMARA</div><p class="gold">PRIVATE VOYAGE PROPOSAL</p><h1>${p.title}</h1><p>Prepared personally for ${contact?.name||"our guest"}</p></section><section class="body"><p class="kicker">YOUR JOURNEY</p><div class="grid"><div><b>Vessel</b><br>${p.vessel}</div><div><b>Destination</b><br>${p.destination}</div><div><b>Dates</b><br>${p.startDate} – ${p.endDate}</div><div><b>Guests</b><br>${p.guests}</div></div>${(p.itinerary||[]).map((x,i)=>`<div class="day"><b>Day ${i+1}</b><p>${x}</p></div>`).join("")}<h2>Investment</h2><p class="price">${p.currency} ${Number(p.price||0).toLocaleString()}</p><p>Deposit: ${p.depositPct}% · Balance according to the current payment policy.</p><p><a class="cta" href="${p.acceptanceLink}">Review and Accept Proposal</a></p><h3>Included</h3><ul>${(p.inclusions||[]).map(x=>`<li>${x}</li>`).join("")}</ul><h3>Not Included</h3><ul>${(p.exclusions||[]).map(x=>`<li>${x}</li>`).join("")}</ul><hr><p class="fine">Controlled documents: Terms v${t("Terms & Conditions")?.version||"—"}; Payment v${t("Cancellation & Payment")?.version||"—"}; Charter Contract v${t("Charter Contract")?.version||"—"}. Generated from Samara ERP proposal ${p.id}.</p></section></div></body></html>`}

