  { id:"CON-001", name:"Guest Shampoo 300ml", category:"Guest Amenities", propertyId:"prop-bayview", area:"Main Store", unit:"bottle", qty:74, reorderLevel:60, reorderQty:120, unitCost:48000, supplier:"Bali Amenities", expiry:"2028-03-31" },
  { id:"CON-002", name:"Marine Cleaning Chemical", category:"Cleaning Materials", propertyId:"prop-s2", area:"Housekeeping Store", unit:"litre", qty:18, reorderLevel:20, reorderQty:40, unitCost:85000, supplier:"Nusa Marine Supply", expiry:"2027-09-30" },
  { id:"CON-003", name:"AA Batteries", category:"Operational Consumables", propertyId:"prop-siloina", area:"Technical Store", unit:"piece", qty:86, reorderLevel:40, reorderQty:100, unitCost:18000, supplier:"Padang General Supply", expiry:"2030-01-01" },
  { id:"CON-004", name:"Warm LED Bulb 9W", category:"Operational Consumables", propertyId:"prop-bayview", area:"Maintenance Store", unit:"piece", qty:11, reorderLevel:20, reorderQty:50, unitCost:62000, supplier:"Labuan Bajo Electrical", expiry:"" }
