const FFE_SEED_INSPECTIONS = [
  { id:"INS-001", assetId:"AST-0002", dueDate:"2026-05-30", assignedTo:"emp-006", status:"Overdue", condition:"", photo:"", comment:"", replacementRequired:false, revisedReplacementDate:"", completedAt:"" },
  { id:"INS-002", assetId:"AST-0006", dueDate:"2026-06-19", assignedTo:"emp-006", status:"Due", condition:"", photo:"", comment:"", replacementRequired:false, revisedReplacementDate:"", completedAt:"" },
  { id:"INS-003", assetId:"AST-0007", dueDate:"2026-07-05", assignedTo:"emp-002", status:"Upcoming", condition:"", photo:"", comment:"", replacementRequired:false, revisedReplacementDate:"", completedAt:"" },
  { id:"INS-004", assetId:"AST-0001", dueDate:"2026-05-30", assignedTo:"emp-002", status:"Completed", condition:"Good", photo:"samara2-sofa-check-20260530.jpg", comment:"Minor wear only; no replacement required.", replacementRequired:false, revisedReplacementDate:"2028-04-15", completedAt:"2026-05-30T10:40:00+08:00" }
];

const FFE_SEED_AUDITS = [
  { id:"AUD-001", propertyId:"prop-otium", date:"2026-06-01", type:"Batch Count", itemId:"BAT-001", expectedQty:44, countedQty:42, difference:-2, reason:"Two glasses broken during previous charter", status:"Reviewed", performedBy:"emp-003", approvedBy:"Operations Manager" },
  { id:"AUD-002", propertyId:"prop-bayview", date:"2026-05-31", type:"Batch Count", itemId:"BAT-002", expectedQty:108, countedQty:104, difference:-4, reason:"Laundry rejects not previously recorded", status:"Investigation Open", performedBy:"emp-006", approvedBy:"" }
];

