  const completeDisposal=()=>{const a=safeAssets.find(x=>x.id===disposalDraft.assetId);if(!a)return showToast("Select an asset");if(!disposalDraft.photo||!disposalDraft.approvedBy)return showToast("Disposal approval and photograph are mandatory");const rec={...disposalDraft,id:ffe163Id("DSP"),saleValue:Number(disposalDraft.saleValue||0),scrapValue:Number(disposalDraft.scrapValue||0),createdAt:ffe163Now(),createdBy:role};setDisposals(rows=>[rec,...ffe163Safe(rows)]);setAssets(rows=>ffe163Safe(rows).map(x=>x.id===a.id?{...x,status:disposalDraft.method==="Sold"?"Sold":"Disposed",disposedAt:disposalDraft.date,disposalId:rec.id}:x));setInspections(rows=>ffe163Safe(rows).map(i=>i.assetId===a.id&&!['Completed','Cancelled'].includes(i.status)?{...i,status:"Cancelled",cancelReason:"Asset disposed"}:i));setReplacements(rows=>ffe163Safe(rows).map(r=>r.assetId===a.id?{...r,disposalStatus:disposalDraft.method}:r));log("Asset",a.id,"Disposed",a.status,disposalDraft.method,disposalDraft.reason);setModal("");showToast("Disposal completed; asset remains permanently searchable")};

  const [standardDraft,setStandardDraft]=useState({name:"",propertyType:"Hotel / Resort",unitType:"Guest Room",itemsText:"Television|Guest-room Electronics|1\nBath towel|Linen|4",active:true});
