  const scanAudit=(sessionId,qr)=>{const s=safeSessions.find(x=>x.id===sessionId);const asset=safeAssets.find(a=>a.qr===qr||a.assetNo===qr);if(!asset)return showToast("QR / asset number not found");const result=asset.propertyId===s.propertyId&&(!s.area||asset.area===s.area)?"Present":"Wrong Location";const scan={assetId:asset.id,result,condition:asset.condition,scannedAt:ffe163Now()};setAuditSessions(rows=>ffe163Safe(rows).map(x=>x.id===s.id?{...x,scans:[...ffe163Safe(x.scans).filter(q=>q.assetId!==asset.id),scan]}:x));log("Audit",s.id,"Asset scanned","",`${asset.assetNo}: ${result}`);showToast(`${asset.assetNo} recorded as ${result}`)};
  const completeAudit=s=>{const expected=safeAssets.filter(a=>a.propertyId===s.propertyId&&(!s.area||a.area===s.area)&&!["Disposed","Sold","Written Off"].includes(a.status));const scannedIds=new Set(ffe163Safe(s.scans).map(x=>x.assetId));const missing=expected.filter(a=>!scannedIds.has(a.id));setAuditSessions(rows=>ffe163Safe(rows).map(x=>x.id===s.id?{...x,status:"Awaiting Supervisor Approval",completedAt:ffe163Now(),missingAssetIds:missing.map(a=>a.id)}:x));missing.forEach(a=>setAudits(rows=>[{id:ffe163Id("AUD"),propertyId:s.propertyId,date:ffe163Today(),type:"Individual QR Audit",itemId:a.id,expectedQty:1,countedQty:0,difference:-1,reason:"Not scanned during physical audit",status:"Investigation Open",performedBy:s.startedBy,approvedBy:""},...ffe163Safe(rows)]));log("Audit",s.id,"Audit completed","In Progress",`${missing.length} missing`);showToast(`${missing.length} missing asset${missing.length===1?"":"s"} sent to investigation`) };

