  const saveSet=()=>{const components=String(setDraft.componentsText||"").split(/\n/).map(line=>{const [name,required,available]=line.split("|");return {name:(name||"").trim(),required:Number(required||1),available:Number(available||0)}}).filter(x=>x.name);const completeSets=components.length?Math.min(...components.map(c=>Math.floor(c.available/Math.max(1,c.required)))):0;const rec={id:ffe163Id("SET"),name:setDraft.name,category:setDraft.category,propertyId:setDraft.propertyId,area:setDraft.area,totalSets:Number(setDraft.totalSets||1),completeSets,status:completeSets>=Number(setDraft.totalSets||1)?"Operational":"Incomplete",components,replacementCost:Number(setDraft.replacementCost||0)};setSets(rows=>[rec,...ffe163Safe(rows)]);log("Set",rec.id,"Set created","",rec);setModal("");showToast("Set created")};
  const setAction=(s,action)=>{if(action==="Complete"){const component=window.prompt("Component added:",s.components.find(c=>c.available<c.required*s.totalSets)?.name||"");if(!component)return;setSets(rows=>ffe163Safe(rows).map(x=>x.id===s.id?{...x,components:x.components.map(c=>c.name===component?{...c,available:c.available+1}:c),completeSets:Math.min(...x.components.map(c=>Math.floor((c.available+(c.name===component?1:0))/Math.max(1,c.required)))),status:"Operational"}:x))}else setSets(rows=>ffe163Safe(rows).map(x=>x.id===s.id?{...x,status:action==="Break Down"?"Broken Down":action}:x));log("Set",s.id,action,s.status,action);showToast(`Set ${action.toLowerCase()} recorded`)};

