function marketingMoney(value,currency="IDR"){
  const n=Number(value||0);
  if(currency==="USD") return new Intl.NumberFormat("en-US",{style:"currency",currency:"USD",maximumFractionDigits:0}).format(n);
  if(n>=1e9) return `IDR ${(n/1e9).toFixed(2)} B`;
  if(n>=1e6) return `IDR ${(n/1e6).toFixed(1)} M`;
  return `IDR ${Math.round(n).toLocaleString("en-US")}`;
}
function marketingTone(value){const s=String(value||"").toLowerCase();if(s.includes("critical")||s.includes("overdue")||s.includes("risk")||s.includes("rejected")||s.includes("missing"))return "red";if(s.includes("pending")||s.includes("review")||s.includes("awaiting")||s.includes("blocked")||s.includes("high"))return "amber";if(s.includes("approved")||s.includes("published")||s.includes("live")||s.includes("ready")||s.includes("completed")||s.includes("converted"))return "green";if(s.includes("draft")||s.includes("new")||s.includes("planned"))return "gray";return "blue";}
function marketingPercent(n,d){return d?Math.round(Number(n||0)/Number(d||1)*100):0;}

