function projectMoney(value){ return shortMoney(Number(value||0)); }
function projectDaysUntil(date){ return date ? Math.ceil((new Date(date)-new Date("2026-06-20T00:00:00+08:00"))/86400000) : null; }
function projectTone(status){
  const s=String(status||"").toLowerCase();
  if(s.includes("critical")||s.includes("failed")||s.includes("overdue")||s.includes("rejected")) return "red";
  if(s.includes("pending")||s.includes("review")||s.includes("risk")||s.includes("late")||s.includes("open")) return "amber";
  if(s.includes("approved")||s.includes("passed")||s.includes("complete")||s.includes("closed")||s.includes("active")) return "green";
  if(s.includes("progress")||s.includes("construction")||s.includes("issued")) return "blue";
  return "gray";
}

