  return <div className="modal-backdrop"><form className="modal hr-form-modal" onSubmit={submit}><div className="modal-head"><div><h2>Add Candidate</h2><p>Add to the searchable talent pool.</p></div><button type="button" onClick={onClose}>×</button></div><div className="form-grid three"><label>Name<input value={form.name} onChange={event => setForm({ ...form, name: event.target.value })}/></label><label>Target role<select value={form.roleId} onChange={event => { const role = hrRole(event.target.value); setForm({ ...form, roleId: event.target.value, expectedSalary: role?.midpoint || 0 }); }}>{HR_ROLE_BANDS.map(role => <option key={role.id} value={role.id}>{role.title}</option>)}</select></label><label>Preferred location<input value={form.preferredLocation} onChange={event => setForm({ ...form, preferredLocation: event.target.value })}/></label><label>Source<input value={form.source} onChange={event => setForm({ ...form, source: event.target.value })}/></label><label>Status<select value={form.status} onChange={event => setForm({ ...form, status: event.target.value })}><option>Talent Pool</option><option>Shortlisted</option><option>Assessment</option><option>Interview</option></select></label><label>Assessment score<input type="number" min="0" max="100" value={form.score} onChange={event => setForm({ ...form, score: event.target.value })}/></label><label>Availability<input value={form.availability} onChange={event => setForm({ ...form, availability: event.target.value })}/></label><label>Expected salary<input type="number" value={form.expectedSalary} onChange={event => setForm({ ...form, expectedSalary: event.target.value })}/></label><label className="span-3">Notes<textarea value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })}/></label></div><div className="modal-actions"><Button type="button" variant="secondary" onClick={onClose}>Cancel</Button><Button type="submit">Add Candidate</Button></div></form></div>;
